(1,1,1,'user','It clicks','english',NULL,'offline','none','2026-11-04 17:07:20.149007'),
(2,1,1,'assistant','**Symptom:** It clicks\n\n> [!NOTE]\n> Offline knowledge — this answer comes from the local reviewed repair library. Gemini was not used.\n\n**What I still need to know:**\n\n- What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\n\n  - Motorcycle\n\n  - Car\n\n  - Not sure\n\n**Limitations:**\n\n- No approved local repair record matched this question closely enough. I will not guess at a repair procedure or specification.\n\n**Next action:** What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\n\n[chips: Motorcycle | Car | Not sure]','english','{\"reply_text\": \"**Symptom:** It clicks\\n\\n> [!NOTE]\\n> Offline knowledge \\u2014 this answer comes from the local reviewed repair library. Gemini was not used.\\n\\n**What I still need to know:**\\n\\n- What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\\n\\n  - Motorcycle\\n\\n  - Car\\n\\n  - Not sure\\n\\n**Limitations:**\\n\\n- No approved local repair record matched this question closely enough. I will not guess at a repair procedure or specification.\\n\\n**Next action:** What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\\n\\n[chips: Motorcycle | Car | Not sure]\", \"language\": \"english\", \"intent\": \"diagnostic_offline\", \"diagnostic_stage\": \"symptom\", \"vehicle_profile\": {\"vehicle_type\": \"motorcycle\", \"make\": \"\", \"model\": \"\", \"year\": \"\", \"variant\": \"\", \"engine_displacement\": \"\", \"fuel_system\": \"\"}, \"symptoms\": [\"It clicks\"], \"missing_questions\": [{\"question\": \"What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\", \"why\": \"Vehicle-specific service information and safe checks depend on the exact model and year.\", \"options\": [\"Motorcycle\", \"Car\", \"Not sure\"]}], \"safety\": {\"severity\": \"none\", \"summary\": \"\", \"warnings\": [], \"stop_use\": false}, \"possible_causes\": [], \"findings\": \"\", \"visible_evidence\": [], \"diagnostic_tests\": [], \"required_tools\": [], \"required_parts\": [], \"repair_steps\": [], \"verification\": [], \"sources\": [], \"next_action\": \"What is the vehicle make, model, and year? A photo of the badge or registration is enough if you are unsure.\", \"related_components\": [], \"limitations\": [\"No approved local repair record matched this question closely enough. I will not guess at a repair procedure or specification.\", \"This is guidance from an automated assistant, not a confirmed diagnosis or a substitute for an in-person inspection.\"], \"offline\": true, \"offline_reason\": \"Gemini is not configured on this server.\", \"chips\": [\"Motorcycle\", \"Car\", \"Not sure\"]}','offline','none','2026-11-04 17:07:20.150610'),
