INSERT INTO `diagnostic_questions` VALUES
(1,1,'starter_sound','What happens exactly when you press the starter button?','Ano ang eksaktong naririnig mo pag pinindot ang starter button?','Ano ang mabatian mo kon pinduton ang starter button?','[{\"label\": \"A. Rapid clicking from under the seat\", \"value\": \"rapid_clicking\", \"cause_hint\": \"battery_dead\"}, {\"label\": \"B. Engine cranks very slowly then dies\", \"value\": \"slow_crank\", \"cause_hint\": \"weak_battery\"}, {\"label\": \"C. Complete silence, no lights on dash\", \"value\": \"dead_silent\", \"cause_hint\": \"blown_fuse\"}, {\"label\": \"D. Cranks strongly but does not catch fire\", \"value\": \"cranks_no_start\", \"cause_hint\": \"no_spark_or_fuel\"}]',1,'2026-11-07 05:07:14.326767'),
(2,1,'sidestand_check','Is your sidestand fully retracted and the kill switch set to RUN?','Nakatiklop ba nang buo ang side stand at naka-RUN ang kill switch?','Nakataklob bala sing bug-os ang side stand kag naka-RUN ang kill switch?','[{\"label\": \"A. Yes, stand is up and kill switch is in RUN\", \"value\": \"switches_ok\"}, {\"label\": \"B. Not sure / stand was down\", \"value\": \"check_switches\"}]',2,'2026-11-07 05:07:14.332128'),
(3,2,'brake_fluid_level','Check the master cylinder sight glass or fluid reservoir — is fluid above the LOWER/MIN line?','Tingnan ang reservoir o sight glass ng preno — lampas ba sa LOWER o MIN line ang fluid?','Tuluka ang reservoir ukon sight glass sang preno — lampas bala sa LOWER ukon MIN mark ang fluid?','[{\"label\": \"A. Fluid is visible and above MIN line\", \"value\": \"fluid_ok\", \"cause_hint\": \"air_in_lines\"}, {\"label\": \"B. Fluid is empty or below MIN line\", \"value\": \"fluid_low\", \"cause_hint\": \"hydraulic_leak\"}, {\"label\": \"C. Fluid is dark brown / cloudy black\", \"value\": \"fluid_contaminated\", \"cause_hint\": \"moisture_contamination\"}]',1,'2026-11-07 05:07:14.372592'),
(4,2,'leak_visual','Do you see any wet oily seepage around the caliper bleeder nipple, banjo bolt, or rubber hose?','May nakikita ka bang tagas o basa ng langis sa caliper bleeder, hose, o fitting?','May nakita ka bala nga basa sang brake fluid sa caliper, hose, ukon fitting?','[{\"label\": \"A. No leaks visible, lines are dry\", \"value\": \"dry_lines\"}, {\"label\": \"B. Yes, wet fluid dripping or weeping\", \"value\": \"active_leak\"}]',2,'2026-11-07 05:07:14.376723'),
(5,3,'overheat_situation','When does the temperature light come on — in slow traffic/idle, or at high speed on the highway?','Kailan umiilaw ang temp light — pag traffic/idle, o pag mabilis ang takbo sa highway?','Kasan-o nagasiga ang temp light — kon traffic/idle, ukon kon madasig ang padalagan?','[{\"label\": \"A. In slow stop-and-go traffic or at idle\", \"value\": \"idle_traffic\", \"cause_hint\": \"cooling_fan\"}, {\"label\": \"B. At cruising speeds or uphill under load\", \"value\": \"highway_speed\", \"cause_hint\": \"thermostat_or_water_pump\"}, {\"label\": \"C. Immediately within 3 minutes of cold start\", \"value\": \"immediate\", \"cause_hint\": \"head_gasket_or_empty\"}]',1,'2026-11-07 05:07:14.423701'),
(6,3,'fan_spinning','When the engine reaches full temperature, does the electric radiator fan spin loudly?','Pag mainit na ang makina, umiikot ba nang malakas ang electric fan ng radiator?','Kon mainit na ang makina, nagatuyok bala sing mabaskog ang electric radiator fan?','[{\"label\": \"A. Yes, fan turns on and blows hot air\", \"value\": \"fan_runs\"}, {\"label\": \"B. No, fan remains completely silent and still\", \"value\": \"fan_dead\"}, {\"label\": \"C. Vehicle is air-cooled (no radiator fan)\", \"value\": \"air_cooled\"}]',2,'2026-11-07 05:07:14.427976'),
(7,4,'drain_timing','Does the battery die while driving on the road, or overnight while parked with the key off?','Namamatay ba ang baterya habang umaandar sa kalsada, o overnight habang nakaparada?','Nagakadulaan bala sing karga ang baterya samtang nagadalagan, ukon sa gab-i samtang nakaparada?','[{\"label\": \"A. While driving \\u2014 engine suddenly dies and lights fade\", \"value\": \"while_driving\", \"cause_hint\": \"charging_failure\"}, {\"label\": \"B. Overnight or after sitting parked 2\\u20133 days\", \"value\": \"overnight_drain\", \"cause_hint\": \"parasitic_draw\"}]',1,'2026-11-07 05:07:14.458933'),
(8,4,'aftermarket_accessories','Are there aftermarket accessories installed (alarm, loud horn, mini-driving lights, USB chargers)?','May mga ikinabit ka bang aftermarket accessories (alarm, mini driving lights, USB charger)?','May mga ginpakabit ka bala nga accessories (alarm, mini driving light, USB charger)?','[{\"label\": \"A. Yes, aftermarket auxiliary lights or alarm installed\", \"value\": \"has_accessories\"}, {\"label\": \"B. No, completely stock factory wiring\", \"value\": \"stock_wiring\"}]',2,'2026-11-07 05:07:14.462172'),
(9,5,'fuel_system_type','Is your engine Electronic Fuel Injection (EFI / Fi) or equipped with a traditional Carburetor?','Naka-Fuel Injection (EFI / Fi) ba ang makina o Carburetor?','Fuel Injection (EFI / Fi) bala ang makina mo ukon Carburetor?','[{\"label\": \"A. Fuel Injected (EFI / Fi / PGM-FI)\", \"value\": \"efi\", \"cause_hint\": \"clogged_injector_or_fuel_pump\"}, {\"label\": \"B. Carburetor (with choke lever)\", \"value\": \"carb\", \"cause_hint\": \"clogged_pilot_main_jet\"}]',1,'2026-11-07 05:07:14.480473'),
(10,5,'choke_reaction','If carbureted, does the engine run better when the choke is engaged?','Kung de-carburetor, gumaganda ba ang andar pag binuksan ang choke?','Kon naka-carburetor, naganami bala ang andar kon ibira ang choke?','[{\"label\": \"A. Yes, runs much better with choke on\", \"value\": \"better_with_choke\", \"cause_hint\": \"lean_fuel_condition\"}, {\"label\": \"B. No difference / engine is EFI\", \"value\": \"no_choke_change\"}]',2,'2026-11-07 05:07:14.483379'),
(11,6,'noise_location','Where is the noise coming from, and does it change with engine speed?','Saan nanggagaling ang ingay — sa itaas ng ulo ng makina, sa gilid, o sa ilalim ng crankcase?','Diin nagahalin ang huni — sa ibabaw sang makina, sa kilid, ukon sa dalom sang crankcase?','[{\"label\": \"A. Light ticking from top cylinder head (sounds like typewriter)\", \"value\": \"top_ticking\", \"cause_hint\": \"valve_clearance\"}, {\"label\": \"B. Rattling/slapping from side cover at idle, quiets at high speed\", \"value\": \"side_rattle\", \"cause_hint\": \"cam_chain_tensioner\"}, {\"label\": \"C. Heavy deep rhythmic thudding from bottom crankcase that increases with throttle\", \"value\": \"deep_knock\", \"cause_hint\": \"rod_bearing_failure\"}]',1,'2026-11-07 05:07:14.519931'),
(12,6,'oil_level_check','Check the oil dipstick/sight glass with engine off on level ground — what is the oil level and color?','Tingnan ang dipstick o sight glass ng langis — anong level at kulay ng langis ng makina?','Tuluka ang dipstick ukon sight glass sang langis — ano ang level kag duag sang langis?','[{\"label\": \"A. Oil is between MIN and MAX, amber/brown\", \"value\": \"oil_good\"}, {\"label\": \"B. Dipstick is completely dry or below MIN mark\", \"value\": \"oil_dry\"}, {\"label\": \"C. Oil is jet black with metallic glitter flakes\", \"value\": \"oil_metal_glitter\"}]',2,'2026-11-07 05:07:14.522882');
