INSERT INTO `diagnostic_symptoms` VALUES
(1,'Motorcycle will not start (Rapid clicking or completely dead)','Electrical & Starting','Pushing the starter button produces rapid machine-gun clicking, dimming dash lights, or complete silence.','motorcycle','warning','Ensure motorcycle is in Neutral on its center stand before testing electrical components.','Electrical & Starting','','','2026-11-07 05:07:14.309214','2026-11-07 05:07:14.309696'),
(2,'Spongy brake lever or soft brake pedal (Loss of braking pressure)','Brake System','Brake lever or pedal travels almost to handlebar/floorboard without solid stopping resistance.','all','critical_stop','CRITICAL SAFETY HAZARD: DO NOT RIDE OR DRIVE. Operating a vehicle with soft or spongy brakes can cause catastrophic collision.','Brake System','','','2026-11-07 05:07:14.368711','2026-11-07 05:07:14.368905'),
(3,'Engine overheating (High coolant temp light or steam)','Cooling System','Temperature warning lamp illuminated on dashboard, boiling coolant bubbling in expansion reservoir, or steam escaping from engine bay.','all','critical_stop','SEVERE SCALD HAZARD: NEVER OPEN A HOT RADIATOR CAP. Boiling pressurized coolant will violently erupt causing severe burns. Allow engine to cool completely for at least 45 minutes.','Cooling System','','','2026-11-07 05:07:14.419776','2026-11-07 05:07:14.420010'),
(4,'Battery drains repeatedly / Battery warning light on dash','Charging System','Battery loses charge after driving or overnight; dashboard battery icon illuminates while driving; headlights dim at idle.','all','warning','Remove metal jewelry and wristwatches before testing alternator/stator terminals to avoid accidental dead-short burns.','Charging System','','','2026-11-07 05:07:14.456055','2026-11-07 05:07:14.456255'),
(5,'Engine hesitates, sputters, or bogs down when twisting throttle / stepping on gas','Fuel & Air Intake','Engine idles smoothly but hesitates, loses power, sputters, or dies whenever throttle is opened for acceleration.','all','warning','Work in well-ventilated open air away from open flames, pilot lights, and smoking materials.','Fuel & Air Intake','','','2026-11-07 05:07:14.477690','2026-11-07 05:07:14.477859'),
(6,'Engine noise (Ticking, rattling, or metallic knocking)','Engine Mechanical','Abnormal acoustic sound from engine: light rhythmic ticking at top cylinder head, side-casing chain clatter, or heavy thudding knock under throttle load.','all','critical_stop','IF NOISE IS A DEEP HEAVY KNOCK FROM CRANKCASE, SHUT OFF ENGINE IMMEDIATELY. Continued running will throw connecting rod through crankcase, destroying the engine and locking wheels.','Engine Mechanical','','','2026-11-07 05:07:14.517062','2026-11-07 05:07:14.517221');
/*!40000 ALTER TABLE `diagnostic_symptoms` ENABLE KEYS */;
