DROP TABLE IF EXISTS `troubleshooting_guides`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `troubleshooting_guides` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `symptom_id` int(11) NOT NULL,
  `possible_cause` varchar(255) NOT NULL,
  `confidence_level` varchar(20) NOT NULL DEFAULT 'Medium',
  `diagnostic_test` longtext DEFAULT NULL,
  `expected_result` longtext DEFAULT NULL,
  `alternative_outcome` longtext DEFAULT NULL,
  `tools_required` longtext DEFAULT NULL,
  `repair_instructions` longtext NOT NULL,
  `advice_notes` longtext DEFAULT NULL,
  `when_to_stop` longtext DEFAULT NULL,
  `source_reference` varchar(255) DEFAULT NULL,
  `source_title` varchar(255) NOT NULL DEFAULT '',
  `source_date` date DEFAULT NULL,
  `review_status` varchar(20) NOT NULL DEFAULT 'draft',
  `reviewed_by_id` int(11) DEFAULT NULL,
  `reviewed_at` datetime(6) DEFAULT NULL,
  `review_notes` longtext NOT NULL DEFAULT '',
  `system` varchar(100) NOT NULL DEFAULT '',
  `component` varchar(120) NOT NULL DEFAULT '',
  `vehicle_type` varchar(20) NOT NULL DEFAULT 'all',
  `manufacturer` varchar(80) NOT NULL DEFAULT '',
  `model` varchar(120) NOT NULL DEFAULT '',
  `variant` varchar(120) NOT NULL DEFAULT '',
  `year_from` smallint(5) unsigned DEFAULT NULL,
  `year_to` smallint(5) unsigned DEFAULT NULL,
  `safety_precautions` longtext NOT NULL DEFAULT '',
  `verification_procedure` longtext NOT NULL DEFAULT '',
  `is_verified` tinyint(1) NOT NULL DEFAULT 0,
  `difficulty_level` varchar(20) NOT NULL DEFAULT 'Beginner',
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `troubleshooting_guides_symptom_id_fk` (`symptom_id`),
  KEY `troubleshooting_guides_reviewed_by_id_fk` (`reviewed_by_id`),
  CONSTRAINT `troubleshooting_guides_reviewed_by_id_fk` FOREIGN KEY (`reviewed_by_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `troubleshooting_guides_symptom_id_fk` FOREIGN KEY (`symptom_id`) REFERENCES `diagnostic_symptoms` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
